INSERT INTO surveys (title, subtitle, audience, institution, questions_count, status, scale, responses_count, target, variables, questions, hypotheses, created_at)
VALUES ('Bộ 1: Ban Giám hiệu & Hội đồng trường — Chiến lược, thể chế và quản trị số vĩ mô', 'Đánh giá ở tầm vĩ mô: Thể chế, chiến lược, quản trị số, phân bổ nguồn lực và lợi thế cạnh tranh tổng thể', 'leadership', 'Đơn vị khảo sát mẫu', 14, 'Active', 'Likert 5', 0, 50, 'STR, LEA, CAP, RES, SER, REA', '[{"code":"INFO_POSITION","text":"Chức vụ / Vị trí công tác","variable":"INFO","type":"choice","section":"demographics","mapsTo":"role","options":["Chủ tịch / Phó Chủ tịch Hội đồng trường","Hiệu trưởng / Phó Hiệu trưởng","Thành viên Hội đồng trường / Đảng ủy viên"]},{"code":"INFO_TENURE","text":"Thâm niên quản lý ở cấp trường","variable":"INFO","type":"choice","section":"demographics","options":["Dưới 3 năm","Từ 3 – 5 năm","Từ 5 – 10 năm","Trên 10 năm"]},{"code":"STR1","text":"Nhà trường đã xây dựng chiến lược phát triển tổng thể, tích hợp rõ ràng các xu hướng số hóa và chuyển đổi giáo dục đại học.","variable":"STR","type":"likert","group":"1. Chiến lược & Thể chế vĩ mô (STR)"},{"code":"STR2","text":"Kế hoạch chiến lược của nhà trường được rà soát, định kỳ điều chỉnh linh hoạt theo sự biến động của môi trường giáo dục.","variable":"STR","type":"likert","group":"1. Chiến lược & Thể chế vĩ mô (STR)"},{"code":"LEA1","text":"Hội đồng trường / Ban Giám hiệu thể hiện tầm nhìn và năng lực lãnh đạo số mạnh mẽ trong chỉ đạo và điều hành.","variable":"LEA","type":"likert","group":"2. Năng lực Lãnh đạo số (LEA)"},{"code":"LEA2","text":"Nhà trường ban hành các cơ chế, thể chế quản trị linh hoạt, phân cấp mạnh mẽ cho các đơn vị để tạo sự chủ động.","variable":"LEA","type":"likert","group":"2. Năng lực Lãnh đạo số (LEA)"},{"code":"CAP1","text":"Cơ cấu tổ chức của nhà trường có khả năng tái cấu trúc và thích ứng nhanh trước các mô hình đào tạo mới.","variable":"CAP","type":"likert","group":"3. Năng lực Thích ứng Tổ chức (CAP)"},{"code":"RES1","text":"Việc phân bổ ngân sách, tài chính và hạ tầng CNTT được ưu tiên gắn liền với các mục tiêu chiến lược trọng điểm.","variable":"RES","type":"likert","group":"4. Phân bổ Nguồn lực & Đầu tư (RES)"},{"code":"RES2","text":"Nhà trường có chính sách thu hút, phát triển và giữ chân đội ngũ nhân sự chất lượng cao đáp ứng chuẩn mực mới.","variable":"RES","type":"likert","group":"4. Phân bổ Nguồn lực & Đầu tư (RES)"},{"code":"SER1","text":"Nhà trường duy trì được vị thế, uy tín và lợi thế cạnh tranh bền vững so với các cơ sở giáo dục đại học khác.","variable":"SER","type":"likert","group":"5. Lợi thế Cạnh tranh & Uy tín (SER)"},{"code":"REA1","text":"Toàn hệ thống nhà trường đã đạt được sự sẵn sàng cao về mọi mặt để thích ứng thành công với các xu hướng giáo dục mới.","variable":"REA","type":"likert","group":"6. Mức độ Sẵn sàng Thích ứng (REA)"},{"code":"REA2","text":"Nhà trường có khả năng dự báo và ứng phó hiệu quả trước các rủi ro, thách thức trong quá trình chuyển đổi tổ chức.","variable":"REA","type":"likert","group":"6. Mức độ Sẵn sàng Thích ứng (REA)"},{"code":"TXT_BARRIER_BGH","text":"Theo Ông/Bà, đâu là rào cản lớn nhất về mặt cơ chế, thể chế hoặc nguồn lực trong quá trình chuyển đổi của nhà trường?","variable":"QUALITATIVE","type":"textarea","placeholder":"Ý kiến về cơ chế, thể chế, phân bổ nguồn lực, văn hóa tổ chức..."},{"code":"TXT_SUGGESTION_BGH","text":"Ông/Bà có đề xuất định hướng chiến lược trọng tâm gì để gia tăng lợi thế cạnh tranh của nhà trường trong 3–5 năm tới?","variable":"QUALITATIVE","type":"textarea","placeholder":"Đề xuất định hướng chiến lược trọng tâm..."}]', '[{"code":"H1","name":"STR ➔ REA","description":"Chiến lược phát triển (STR) tác động thuận chiều đến mức độ sẵn sàng chuyển đổi (REA)","independent":"STR","dependent":"REA","status":"pending"},{"code":"H2","name":"LEA ➔ REA","description":"Lãnh đạo số (LEA) tác động thuận chiều đến mức độ sẵn sàng chuyển đổi (REA)","independent":"LEA","dependent":"REA","status":"pending"},{"code":"H3","name":"CAP ➔ SER","description":"Năng lực thích ứng tổ chức (CAP) có tác động tích cực đến lợi thế cạnh tranh (SER)","independent":"CAP","dependent":"SER","status":"pending"},{"code":"H4","name":"RES ➔ REA","description":"Nguồn lực và ngân sách (RES) tác động thuận chiều đến sự sẵn sàng tổ chức (REA)","independent":"RES","dependent":"REA","status":"pending"}]', NOW());

INSERT INTO surveys (title, subtitle, audience, institution, questions_count, status, scale, responses_count, target, variables, questions, hypotheses, created_at)
VALUES ('Bộ 2: Trưởng / Phó Khoa, Phòng / Ban — Triển khai chiến lược và quy trình vận hành cấp trung', 'Đánh giá ở cấp trung: Triển khai chiến lược, quy trình vận hành, quản lý nhân sự và chất lượng dịch vụ nội bộ', 'dept_head', 'Đơn vị khảo sát mẫu', 14, 'Active', 'Likert 5', 0, 80, 'STR, LEA, CAP, RES, SER, REA', '[{"code":"INFO_POSITION","text":"Chức vụ / Vị trí công tác","variable":"INFO","type":"choice","section":"demographics","mapsTo":"role","options":["Trưởng Khoa / Viện trưởng đào tạo","Phó Trưởng Khoa / Phó Viện trưởng","Trưởng Phòng / Ban / Trung tâm chức năng","Phó Trưởng Phòng / Ban / Trung tâm"]},{"code":"INFO_TENURE","text":"Thâm niên quản lý ở cấp đơn vị","variable":"INFO","type":"choice","section":"demographics","options":["Dưới 3 năm","Từ 3 – 5 năm","Từ 5 – 10 năm","Trên 10 năm"]},{"code":"STR1","text":"Đơn vị của tôi hiểu rõ và chủ động cụ thể hóa các mục tiêu chiến lược của nhà trường thành kế hoạch hành động.","variable":"STR","type":"likert","group":"1. Triển khai Chiến lược tại đơn vị (STR)"},{"code":"STR2","text":"Kế hoạch hoạt động của đơn vị được liên kết chặt chẽ với các chỉ số đánh giá hiệu quả (KPIs) chung của trường.","variable":"STR","type":"likert","group":"1. Triển khai Chiến lược tại đơn vị (STR)"},{"code":"LEA1","text":"Lãnh đạo đơn vị tích cực hỗ trợ, tạo điều kiện cho cán bộ/giảng viên ứng dụng các phương pháp và quy trình làm việc mới.","variable":"LEA","type":"likert","group":"2. Lãnh đạo cấp trung & Đổi mới (LEA)"},{"code":"LEA2","text":"Lãnh đạo đơn vị thường xuyên khen thưởng, động viên các ý tưởng đổi mới sáng tạo từ cán bộ/giảng viên.","variable":"LEA","type":"likert","group":"2. Lãnh đạo cấp trung & Đổi mới (LEA)"},{"code":"CAP1","text":"Quy trình phối hợp công việc giữa đơn vị của tôi với các phòng/khoa/ban khác diễn ra mượt mà, giảm bớt thủ tục hành chính.","variable":"CAP","type":"likert","group":"3. Năng lực Quy trình & Phối hợp (CAP)"},{"code":"CAP2","text":"Đơn vị có khả năng xử lý linh hoạt và nhanh chóng các sự cố phát sinh trong quá trình vận hành.","variable":"CAP","type":"likert","group":"3. Năng lực Quy trình & Phối hợp (CAP)"},{"code":"RES1","text":"Trang thiết bị, phần mềm quản lý và hạ tầng công nghệ được cung cấp đầy đủ, đáp ứng tốt nhu cầu làm việc của đơn vị.","variable":"RES","type":"likert","group":"4. Nguồn lực & Hạ tầng đơn vị (RES)"},{"code":"RES2","text":"Cán bộ/nhân sự tại đơn vị thường xuyên được bồi dưỡng nâng cao năng lực chuyên môn và kỹ năng số.","variable":"RES","type":"likert","group":"4. Nguồn lực & Hạ tầng đơn vị (RES)"},{"code":"SER1","text":"Đơn vị duy trì chất lượng phục vụ/hỗ trợ cao đối với các đơn vị khác, giảng viên và người học.","variable":"SER","type":"likert","group":"5. Chất lượng Dịch vụ & Hỗ trợ (SER)"},{"code":"REA1","text":"Đơn vị của tôi đạt mức độ sẵn sàng cao trong việc thay đổi thói quen làm việc để đáp ứng yêu cầu chuyển đổi chung.","variable":"REA","type":"likert","group":"6. Mức độ Sẵn sàng Chuyển đổi (REA)"},{"code":"TXT_BARRIER_DEPT","text":"Khó khăn hoặc điểm nghẽn lớn nhất mà đơn vị của Thầy/Cô gặp phải trong quy trình vận hành và phối hợp liên phòng ban là gì?","variable":"QUALITATIVE","type":"textarea","placeholder":"Ý kiến về quy trình, thủ tục hành chính, liên thông dữ liệu..."},{"code":"TXT_SUGGESTION_DEPT","text":"Thầy/Cô có đề xuất gì để cải tiến cơ chế phối hợp và phân quyền cho cấp đơn vị khoa/phòng ban hiệu quả hơn?","variable":"QUALITATIVE","type":"textarea","placeholder":"Đề xuất cải tiến cơ chế quản trị và phân quyền..."}]', '[{"code":"H1","name":"STR ➔ CAP","description":"Hiểu rõ chiến lược (STR) tác động tích cực đến năng lực phối hợp quy trình (CAP)","independent":"STR","dependent":"CAP","status":"pending"},{"code":"H2","name":"LEA ➔ REA","description":"Lãnh đạo đơn vị đổi mới (LEA) thúc đẩy mức độ sẵn sàng thay đổi (REA)","independent":"LEA","dependent":"REA","status":"pending"},{"code":"H3","name":"RES ➔ SER","description":"Hạ tầng và bồi dưỡng nhân lực (RES) tác động thuận chiều đến chất lượng phục vụ (SER)","independent":"RES","dependent":"SER","status":"pending"}]', NOW());

INSERT INTO surveys (title, subtitle, audience, institution, questions_count, status, scale, responses_count, target, variables, questions, hypotheses, created_at)
VALUES ('Bộ 3: Giảng viên / Giáo viên / Nhân viên — Công cụ làm việc, phương pháp giảng dạy và văn hóa đổi mới', 'Đánh giá trực tiếp: Công cụ làm việc, phương pháp giảng dạy, văn hóa đổi mới và sự hỗ trợ từ tổ chức', 'lecturer_staff', 'Đơn vị khảo sát mẫu', 14, 'Active', 'Likert 5', 0, 150, 'STR, LEA, CAP, RES, SER, REA', '[{"code":"INFO_POSITION","text":"Vị trí công tác","variable":"INFO","type":"choice","section":"demographics","mapsTo":"role","options":["Giảng viên trực tiếp giảng dạy","Giáo viên / Trợ giảng","Chuyên viên / Nhân viên hành chính nghiệp vụ","Nghiên cứu viên"]},{"code":"INFO_EDUCATION","text":"Trình độ chuyên môn cao nhất","variable":"INFO","type":"choice","section":"demographics","options":["Cử nhân / Kỹ sư","Thạc sĩ","Tiến sĩ","Phó Giáo sư / Giáo sư"]},{"code":"STR1","text":"Tôi được phổ biến rõ ràng về định hướng phát triển và các chiến lược chuyển đổi của nhà trường.","variable":"STR","type":"likert","group":"1. Nhận thức Chiến lược (STR)"},{"code":"LEA1","text":"Lãnh đạo nhà trường/khoa luôn lắng nghe, chia sẻ và đồng hành cùng giảng viên/nhân viên khi triển khai cái mới.","variable":"LEA","type":"likert","group":"2. Sự Đồng hành của Lãnh đạo (LEA)"},{"code":"CAP1","text":"Tôi chủ động áp dụng các phương pháp giảng dạy hiện đại, công nghệ số hoặc quy trình mới vào công việc chuyên môn.","variable":"CAP","type":"likert","group":"3. Năng lực Thích ứng Chuyên môn (CAP)"},{"code":"CAP2","text":"Bản thân tôi có khả năng thích ứng nhanh với các thay đổi về công nghệ và quy trình làm việc tại trường.","variable":"CAP","type":"likert","group":"3. Năng lực Thích ứng Chuyên môn (CAP)"},{"code":"RES1","text":"Hạ tầng CNTT, mạng Internet và phần mềm giảng dạy/quản lý của trường hoạt động ổn định và hiệu quả.","variable":"RES","type":"likert","group":"4. Hạ tầng & Môi trường Làm việc (RES)"},{"code":"RES2","text":"Cơ sở vật chất, phòng làm việc/giảng dạy được trang bị đầy đủ, tạo môi trường làm việc thuận lợi.","variable":"RES","type":"likert","group":"4. Hạ tầng & Môi trường Làm việc (RES)"},{"code":"SER1","text":"Nhà trường cung cấp các khóa đào tạo, tập huấn thiết thực giúp tôi nâng cao kỹ năng ứng dụng công nghệ/chuyển đổi.","variable":"SER","type":"likert","group":"5. Đào tạo & Tiếp nhận Phản hồi (SER)"},{"code":"SER2","text":"Các kênh phản hồi, góp ý của cán bộ/giảng viên được nhà trường ghi nhận và phản hồi kịp thời.","variable":"SER","type":"likert","group":"5. Đào tạo & Tiếp nhận Phản hồi (SER)"},{"code":"REA1","text":"Tôi sẵn sàng điều chỉnh thói quen và nâng cao năng lực cá nhân để đáp ứng các yêu cầu chuyển đổi của nhà trường.","variable":"REA","type":"likert","group":"6. Thái độ Sẵn sàng & Niềm tin (REA)"},{"code":"REA2","text":"Tôi tin tưởng vào sự thành công và phát triển bền vững của nhà trường trong giai đoạn chuyển đổi hiện nay.","variable":"REA","type":"likert","group":"6. Thái độ Sẵn sàng & Niềm tin (REA)"},{"code":"TXT_BARRIER_STAFF","text":"Thầy/Cô/Anh/Chị gặp khó khăn gì nhiều nhất về hạ tầng, công cụ số hay thời gian làm việc hiện nay?","variable":"QUALITATIVE","type":"textarea","placeholder":"Ý kiến về công cụ, phần mềm, thiết bị hoặc thời gian..."},{"code":"TXT_SUGGESTION_STAFF","text":"Thầy/Cô/Anh/Chị có nguyện vọng hoặc đề xuất gì về chính sách đãi ngộ, tập huấn để an tâm cống hiến tốt hơn?","variable":"QUALITATIVE","type":"textarea","placeholder":"Đề xuất về tập huấn, đãi ngộ và môi trường..."}]', '[{"code":"H1","name":"STR ➔ REA","description":"Nhận thức chiến lược (STR) tác động tích cực đến sự sẵn sàng đổi mới cá nhân (REA)","independent":"STR","dependent":"REA","status":"pending"},{"code":"H2","name":"LEA ➔ CAP","description":"Sự đồng hành của lãnh đạo (LEA) thúc đẩy năng lực ứng dụng công nghệ (CAP)","independent":"LEA","dependent":"CAP","status":"pending"},{"code":"H3","name":"RES ➔ CAP","description":"Hạ tầng và điều kiện làm việc (RES) nâng cao năng lực thích ứng chuyên môn (CAP)","independent":"RES","dependent":"CAP","status":"pending"},{"code":"H4","name":"SER ➔ REA","description":"Tập huấn và tiếp nhận phản hồi (SER) củng cố niềm tin và sự thích ứng cá nhân (REA)","independent":"SER","dependent":"REA","status":"pending"}]', NOW());

INSERT INTO surveys (title, subtitle, audience, institution, questions_count, status, scale, responses_count, target, variables, questions, hypotheses, created_at)
VALUES ('Bộ 4: Người học & Cựu người học — Trải nghiệm dịch vụ đào tạo, môi trường và uy tín thương hiệu', 'Đánh giá từ góc độ thụ hưởng: Trải nghiệm người học, chất lượng dịch vụ đào tạo, môi trường và giá trị thương hiệu', 'student_alumni', 'Đơn vị khảo sát mẫu', 14, 'Active', 'Likert 5', 0, 200, 'SER, RES, CAP, STR, REA', '[{"code":"INFO_POSITION","text":"Đối tượng người học","variable":"INFO","type":"choice","section":"demographics","mapsTo":"role","options":["Sinh viên đang theo học (Năm 1 - 2)","Sinh viên đang theo học (Năm 3 - 4)","Học viên Sau đại học (ThS, NCS)","Cựu người học / Cựu sinh viên"]},{"code":"INFO_MAJOR","text":"Khối ngành đào tạo","variable":"INFO","type":"choice","section":"demographics","options":["Khoa học Tự nhiên & Kỹ thuật","Kinh tế, Quản trị & Luật","Khoa học Xã hội, Nhân văn & Sư phạm"]},{"code":"SER1","text":"Chương trình đào tạo mang tính cập nhật, thực tiễn và đáp ứng tốt nhu cầu của thị trường lao động.","variable":"SER","type":"likert","group":"1. Chất lượng Dịch vụ Đào tạo & Hỗ trợ (SER)"},{"code":"SER2","text":"Giảng viên sử dụng các phương pháp giảng dạy tích cực, ứng dụng công nghệ và tương tác hiệu quả với người học.","variable":"SER","type":"likert","group":"1. Chất lượng Dịch vụ Đào tạo & Hỗ trợ (SER)"},{"code":"SER3","text":"Các dịch vụ hành chính (xác nhận học vụ, bảng điểm, đăng ký môn học...) được thực hiện nhanh chóng, tiện lợi trên nền tảng số.","variable":"SER","type":"likert","group":"1. Chất lượng Dịch vụ Đào tạo & Hỗ trợ (SER)"},{"code":"SER4","text":"Các hoạt động hỗ trợ người học (tư vấn tâm lý, hướng nghiệp, học bổng...) được nhà trường thực hiện chu đáo, chuyên nghiệp.","variable":"SER","type":"likert","group":"1. Chất lượng Dịch vụ Đào tạo & Hỗ trợ (SER)"},{"code":"RES1","text":"Phòng học, phòng thí nghiệm, thư viện và hạ tầng Internet của trường đáp ứng tốt nhu cầu học tập và nghiên cứu.","variable":"RES","type":"likert","group":"2. Môi trường Cơ sở vật chất & Học liệu số (RES)"},{"code":"RES2","text":"Các nền tảng học tập trực tuyến (LMS, phần mềm học tập) hỗ trợ đắc lực cho quá trình tự học của tôi/người học.","variable":"RES","type":"likert","group":"2. Môi trường Cơ sở vật chất & Học liệu số (RES)"},{"code":"CAP1","text":"Nhà trường nhanh chóng tiếp thu ý kiến đóng góp của người học/cựu sinh viên để cải thiện chất lượng dịch vụ đào tạo.","variable":"CAP","type":"likert","group":"3. Năng lực Lắng nghe & Tiếp thu (CAP)"},{"code":"STR1","text":"Nhà trường thể hiện định hướng phát triển hiện đại, tiên phong trong ứng dụng công nghệ và đổi mới sáng tạo.","variable":"STR","type":"likert","group":"4. Định hướng Tiên phong Đổi mới (STR)"},{"code":"REA1","text":"Tôi nhận thấy nhà trường có khả năng thích ứng tốt và duy trì chất lượng đào tạo ổn định trước những thay đổi.","variable":"REA","type":"likert","group":"5. Uy tín & Sự Hài lòng Thụ hưởng (REA)"},{"code":"REA2","text":"Tôi hài lòng và tự hào về uy tín, chất lượng đào tạo của nhà trường khi học tập hoặc giới thiệu cho người khác.","variable":"REA","type":"likert","group":"5. Uy tín & Sự Hài lòng Thụ hưởng (REA)"},{"code":"TXT_BARRIER_STUDENT","text":"Những rào cản hoặc điểm chưa hài lòng lớn nhất mà Bạn gặp phải về dịch vụ hoặc cơ sở vật chất của trường là gì?","variable":"QUALITATIVE","type":"textarea","placeholder":"Ý kiến về thủ tục học vụ, Wifi, học liệu, phòng học..."},{"code":"TXT_SUGGESTION_STUDENT","text":"Bạn có mong muốn hoặc đề xuất cụ thể nào để nhà trường nâng cấp trải nghiệm học tập và hỗ trợ sinh viên tốt hơn?","variable":"QUALITATIVE","type":"textarea","placeholder":"Đề xuất cải tiến dịch vụ người học và cơ sở vật chất..."}]', '[{"code":"H1","name":"RES ➔ SER","description":"Môi trường CSVC và LMS (RES) tác động thuận chiều đến chất lượng đào tạo (SER)","independent":"RES","dependent":"SER","status":"pending"},{"code":"H2","name":"SER ➔ REA","description":"Chất lượng dịch vụ đào tạo (SER) tác động tích cực đến sự hài lòng và tự hào thương hiệu (REA)","independent":"SER","dependent":"REA","status":"pending"},{"code":"H3","name":"CAP ➔ REA","description":"Năng lực lắng nghe phản hồi (CAP) củng cố niềm tin và sự gắn kết người học (REA)","independent":"CAP","dependent":"REA","status":"pending"}]', NOW());

